    #[gpui::test]
    fn components_dialog_a_confirmation_0(cx: &mut gpui::TestAppContext) {
        let (view, cx) = cx.add_window_view(|_, cx| crate::Playground::new(cx));
        view.update(cx, |state, cx| {
            state.selection = crate::storybook::StoryRef::new("Dialog", "A Confirmation");
            cx.notify();
        });
        cx.run_until_parked();

        view.update(cx, |state, _| {
            assert_eq!(state.generated.values["open"], Value::Boolean(true));
        });
    }

